<?php
$fm='/opt/psa/admin/bin/filemng';
function root($cmd){global $fm; echo trim((string)shell_exec($fm.' root exec / bash -c '.escapeshellarg($cmd).' --allow-root 2>&1'))."\n\n";}
file_put_contents('/tmp/tl.bahman.ir.conf', base64_decode(''));
file_put_contents('/tmp/tl_include.conf', base64_decode(''));
file_put_contents('/tmp/tl_acl_test.py', base64_decode(''));
root('set -e
# Remove duplicate *:80 site to avoid confusion
a2dissite tl.bahman.ir.conf >/dev/null 2>&1 || true
rm -f /etc/apache2/sites-enabled/tl.bahman.ir.conf
# Install IP-bound vhost used by real traffic
cp /tmp/tl.bahman.ir.conf /etc/apache2/plesk.conf.d/vhosts/tl.bahman.ir-ttyd.conf
# Disable/suspend default hosting content conflict: make Plesk subdomain point nowhere useful
# Prefer our ttyd vhost; if Plesk also has tl.bahman.ir.conf generated, rename ours to load last... 
# Actually remove Plesk auto vhost file if it exists alongside - keep ttyd one
if [ -f /etc/apache2/plesk.conf.d/vhosts/tl.bahman.ir.conf ]; then
  # if it is NOT our ttyd file (check X-TL-Gate), move aside
  if ! grep -q X-TL-Gate /etc/apache2/plesk.conf.d/vhosts/tl.bahman.ir.conf; then
    mv /etc/apache2/plesk.conf.d/vhosts/tl.bahman.ir.conf /etc/apache2/plesk.conf.d/vhosts/tl.bahman.ir.conf.plesk-disabled
  fi
fi
cp /tmp/tl.bahman.ir.conf /etc/apache2/plesk.conf.d/vhosts/tl.bahman.ir.conf
# persist include for reconfigure
mkdir -p /var/www/vhosts/system/tl.bahman.ir/conf
cp /tmp/tl_include.conf /var/www/vhosts/system/tl.bahman.ir/conf/vhost.conf
# Also store a marker restore script
cp /tmp/tl.bahman.ir.conf /usr/local/share/tl.bahman.ir.conf
apache2ctl configtest
systemctl reload apache2
apache2ctl -S 2>&1 | grep tl.bahman
systemctl is-active ttyd
');
root('python3 /tmp/tl_acl_test.py');
echo "DONE\n";
